"""Prospective full A58 workload; every arm/seed/role retained independent of outcomes."""
def workload(roles,plan_position_totals):
    if len(plan_position_totals)!=2:raise ValueError('both fixed seed plans required')
    stress=['stress_selection','stress_calibration'];main=['selection','calibration'];all_roles=['fit','inner_cal',*main,*stress]
    return {'formal_models':8,'formal_optimizer_updates':48000,'a08_dense_windows':sum(roles[k]['a08_stride2_windows'] for k in all_roles),'a08_original_stress_windows':sum(roles[k]['a08_stride5_windows'] for k in stress),'new_JEPA_chunks':roles['fit']['jepa_chunks']+sum(roles[k]['jepa_chunks'] for k in stress),'source_cache_sequence_writes':2*sum(roles[k]['sequences'] for k in all_roles)+sum(roles[k]['sequences'] for k in stress),'head_training_valid_positions':4*sum(plan_position_totals),'inner_MAP_positions':8*3*roles['inner_cal']['positions'],'main_MAP_positions':16*sum(roles[k]['positions'] for k in main),'stress_MAP_positions':8*sum(roles[k]['positions'] for k in stress),'inner_sequence_decodes':24*roles['inner_cal']['sequences'],'main_sequence_decodes':16*sum(roles[k]['sequences'] for k in main),'stress_sequence_decodes':8*sum(roles[k]['sequences'] for k in stress),'bootstrap_replicates':5000,'planned_paired_comparisons_upper':132,'main_logical_systems':16,'stress_fixed6000_systems':8}

def caps_fit(b,new_gpu,new_cpu,new_peak,end_epoch):
    return new_gpu<=b['new_GPUjob_h'] and b['prior_GPUjob_h']+new_gpu<=b['cumulative_GPUjob_h'] and new_cpu<=b['new_CPUcore_h'] and b['prior_summed_measured_CPUreceipt_h']+b['prior_setup_budget_allowance_h']+new_cpu<=b['cumulative_CPUcore_h'] and new_peak<=b['new_peak_bytes'] and b['prior_tracked_storage_upper_bytes']+new_peak<=b['cumulative_peak_upper_bytes'] and end_epoch<=min(b['new_deadline'],b['cumulative_deadline'])
